import { useSetRecoilState } from "recoil";
import IToDo from "../interfaces/IToDo";
import { Category, toDoListState } from "../atoms";
import { ButtonHTMLAttributes, ReactElement } from "react";
import styled from "styled-components";

const Cell = styled.li`
	display: flex;
	justify-content: space-between;
	/* background-color: ${(props) => props.theme.bgColors.dimmed}; */
	color: ${(props) => props.theme.textColors.normal};
	margin-bottom: 12px;
	border-radius: 16px;
	font-size: 18px;
	/* font-weight: bold; */
`;

const Button = styled.button`
	text-align: center;
	font-size: 12px;
	font-weight: 400;
	padding: 6px 20px;
	border-radius: 12px; 
	background-color: ${(props) => props.theme.bgColors.dimmed};
	color: ${(props) => props.theme.textColors.normal};
`;

function ToDo({ id, text, category }: IToDo) {
	const setToDoList = useSetRecoilState(toDoListState);

	const updateToDoCategory = (newCategory: IToDo["category"]) => {
		setToDoList(oldToDoList => {
			const targetIdx = oldToDoList.findIndex( todo => todo.id === id );
			const front = oldToDoList.slice(0, targetIdx)
			const back = oldToDoList.slice(targetIdx+1)
			const newToDo = {id, text, category: newCategory}
			return [...front, newToDo, ...back];
		});
		// setToDoList(oldToDoList => {
		// 	const newList = oldToDoList.map( todo => {
		// 		return todo.id === id ? {id: todo.id, text: todo.text, category: newCategory} : todo
		// 	});

		// 	return newList;
		// });
	};

	return (
		<Cell>
			<span>{text}</span>
			<div style={{display:"flex", gap:"10px"}}>
				{category === Category.to_do && <button onClick={() => updateToDoCategory(Category.to_do)}>to do</button>}
				{category === Category.in_progress && <button onClick={() => updateToDoCategory(Category.in_progress)}>in progress</button>}
				{category === Category.done && <button onClick={() => updateToDoCategory(Category.done)}>done</button>}
			{category !== "DOING" && <button onClick={() => updateToDoCategory("DOING")}>DOING</button>}
			{category !== "DONE" && <button onClick={() => updateToDoCategory("DONE")}>DONE</button>}
			</div>
		</Cell>
	);
}

export default ToDo;
